{
  "status": "ok",
  "rules": [
    {
      "field": "ground_sheet",
      "property": "visible",
      "condition": {
        "op": "eq",
        "field": "weather",
        "value": "rainy"
      },
      "quote": "Ground sheet status: show if and only if weather is rainy."
    },
    {
      "field": "ground_sheet",
      "property": "required",
      "condition": {
        "op": "all",
        "args": [
          {"op": "gte", "field": "soil_boxes", "value": 2},
          {"op": "eq", "field": "powered_tool", "value": true}
        ]
      },
      "quote": "Ground sheet status: when shown, an answer is mandatory if and only if there are at least 2 soil boxes and a powered tool is selected."
    },
    {
      "field": "return_plan",
      "property": "visible",
      "condition": true,
      "quote": "Return plan status: show for every request."
    },
    {
      "field": "return_plan",
      "property": "required",
      "condition": {
        "op": "all",
        "args": [
          {"op": "eq", "field": "powered_tool", "value": true},
          {"op": "ne", "field": "return_before_dusk", "value": true}
        ]
      },
      "quote": "Return plan status: an answer is mandatory if and only if a powered tool is selected and return is not before dusk."
    }
  ]
}
